/* Proves the bundled-benchmark path works, without bundling anything real.
 *
 * A temporary benchmarks.json is written from a synthetic fixture, the browser
 * is driven against it, and the real (empty) file is restored afterwards
 * whatever happens. Nothing invented here ever reaches a reader.
 */
const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');
const TMP = process.env.PRC_TMP || '/tmp/prc';
const CHROME = process.env.PRC_CHROME || '/opt/pw-browsers/chromium-1194/chrome-linux/chrome';
const BASE_URL = process.env.PRC_URL || 'http://127.0.0.1:8781/tool/';
const BUNDLE = path.resolve(__dirname, '../../tool/data/benchmarks.json');

let pass = 0; const fails = [];
function ok(n, c, d) {
  if (c) { pass++; console.log('  pass  ' + n); }
  else { fails.push(n); console.log('  FAIL  ' + n + (d ? '  -- ' + d : '')); }
}

/* a synthetic series: grows at exactly 10% a year, so every statistic is known */
function fixture() {
  const series = [];
  let t = Date.UTC(2005, 0, 3), v = 1000;
  const end = Date.UTC(2025, 0, 1);
  while (t <= end) {
    const d = new Date(t);
    if (d.getUTCDay() !== 0 && d.getUTCDay() !== 6) {
      series.push([d.toISOString().slice(0, 10), Number(v.toFixed(4))]);
    }
    v *= Math.pow(1.10, 1 / 365.2425);
    t += 86400000;
  }
  return {
    asOf: series[series.length - 1][0],
    benchmarks: [{
      name: 'FIXTURE INDEX TRI (synthetic, test only)',
      kind: 'TRI',
      source: 'synthetic test fixture, not real market data',
      licence: 'test only',
      note: 'Generated by the test suite to exercise the bundled path.',
      firstDate: series[0][0],
      lastDate: series[series.length - 1][0],
      points: series.length,
      series: series
    }]
  };
}

const original = fs.readFileSync(BUNDLE, 'utf8');
const DATA = fixture();
const FIRST = DATA.benchmarks[0].firstDate;          // e.g. 2005-01-03
const LAST = DATA.benchmarks[0].lastDate;
/* the same dates as the screen renders them: 03-Jan-2005 */
function pretty(iso) {
  const [y, m, d] = iso.split('-');
  return d + '-' + ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][+m - 1] + '-' + y;
}

(async () => {
  fs.writeFileSync(BUNDLE, JSON.stringify(DATA));
  const browser = await chromium.launch({ executablePath: CHROME });
  try {
    const ctx = await browser.newContext({ viewport: { width: 390, height: 844 } });
    const page = await ctx.newPage();
    const errors = [];
    page.on('pageerror', e => errors.push(e.message));

    await page.goto(BASE_URL + '#history', { waitUntil: 'networkidle' });
    ok('a bundled benchmark is offered without any upload',
       await page.locator('#bm-list .tile').count() === 1);
    const tile = await page.locator('#bm-list').innerText();
    ok('the tile says whether dividends are included', /Total Return Index/.test(tile));
    ok('the tile shows the real date range',
       tile.includes(FIRST + ' to ' + LAST), tile);

    await page.click('#bm-list .tile');
    await page.waitForSelector('#h-out .result', { timeout: 20000 });
    const out = await page.locator('#h-out').innerText();

    ok('the dataset is described before the results', /About this data/.test(out));
    ok('the source is stated', /synthetic test fixture/.test(out));
    ok('the licence is stated', /Used under/.test(out));
    ok('the first and last dates are stated',
       out.includes(pretty(FIRST)) && out.includes(pretty(LAST)),
       pretty(FIRST) + ' / ' + pretty(LAST));
    ok('it says the results describe this dataset only', /and nothing outside\s+those dates|nothing outside/.test(out));
    ok('it says the data is fixed, not live', /fixed, not live/.test(out));
    ok('it makes no forecast claim', /nothing in it forecasts/.test(out));

    ok('rolling statistics are calculated automatically', /Median annual return/.test(out));
    const spread = await page.locator('#h-out table.spread td').allInnerTexts();
    ok('a 10% series measures 10% across every percentile',
       spread.every(v => v.trim() === '10.0%'), spread.join('|'));
    ok('positive and negative shares are shown', /Made money/i.test(out) && /Lost money/i.test(out));
    ok('the distribution chart is drawn', await page.locator('#h-out svg').count() >= 1);
    ok('the hurdle-rate box is offered', await page.locator('#rate-market').isVisible());

    await page.fill('#rate-market', '12');
    await page.waitForTimeout(250);
    ok('a hurdle above the series is beaten by nothing',
       (await page.locator('#rateout-market').textContent()).trim() === '0%');
    await page.fill('#rate-market', '8');
    await page.waitForTimeout(250);
    ok('a hurdle below the series is beaten by everything',
       (await page.locator('#rateout-market').textContent()).trim() === '100%');

    for (const years of ['3 years', '10 years']) {
      await page.locator('#h-horizons .chip', { hasText: years }).click();
      await page.waitForTimeout(300);
      ok('switching to ' + years + ' recalculates from the bundled data',
         new RegExp(years.split(' ')[0] + '-year period').test(await page.locator('#h-out').innerText()));
    }

    ok('the About screen shows the data date',
       (await page.locator('#asof').textContent()).trim() === 'through ' + LAST,
       await page.locator('#asof').textContent());
    ok('no script errors', errors.length === 0, errors.slice(0, 2).join(' | '));
    await page.screenshot({ path: TMP + '/shots/22-bundled.png', fullPage: true });
  } finally {
    fs.writeFileSync(BUNDLE, original);      // always put the real file back
    await browser.close();
  }
  const restored = fs.readFileSync(BUNDLE, 'utf8');
  ok('the real bundle is restored, unchanged', restored === original);
  ok('and it still contains no invented data',
     (JSON.parse(restored).benchmarks || []).length === 0);

  console.log('\n' + pass + ' passed, ' + fails.length + ' failed');
  if (fails.length) { console.log('FAILED:\n  ' + fails.join('\n  ')); process.exit(1); }
})();
